'use strict';
const letters=['А','Б','В','Г','Д'];
// Coordinates in original 4×4 grid, origin at upper left.
const paths=['M1 0V2H3V4','M0 4L4 0','M1 4V1H2V3H3V0','M0 1L4 3','M1 4V1H2V3H3V1H4'];
const regions=[[[0,0],[1,0],[1,2],[3,2],[3,4],[0,4]],[[0,0],[4,0],[0,4]],[[0,0],[3,0],[3,3],[2,3],[2,1],[1,1],[1,4],[0,4]],[[0,0],[4,0],[4,3],[0,1]],[[1,4],[1,1],[2,1],[2,3],[3,3],[3,1],[4,1],[4,4]]];
const steps=[['Твой выбор','У какого квадрата части не равны?','Квадрат разделён на две фигуры. Выбери рисунок, на котором их площади разные. Не спеши: форма может обманывать!'],['Идея','Одна клетка — одна мера площади','Во всех квадратах 4 ряда по 4 клетки: 4 × 4 = 16. Если части равны, каждой достанется 8 клеток.'],['Считаем','Посчитаем оранжевую часть','Посмотри на рисунок Д. В оранжевой части три клетки в одном столбике, одна — посередине и ещё три — справа.'],['Сравниваем','Клетки переезжают — площадь остаётся','Разложим клетки в два ряда. У каждой оранжевой клетки есть зелёная пара, но две зелёные клетки остаются лишними.'],['Открытие','Ответ Д: 7 клеток и 9 клеток','7 ≠ 9. Значит, площади разные! А в каждом из остальных вариантов обе части занимают по 8 клеток.']];
let step=0,selected=null,playing=false,timer=null,moveTimer=null,arranged=false;
const $=id=>document.getElementById(id);
function grid(){return [1,2,3].map(n=>`<path class="grid-line" d="M${n} 0V4M0 ${n}H4"/>`).join('')}
function square(i,filled=false){return `<svg viewBox="-.2 -.2 4.4 4.4" role="img" aria-label="Рисунок ${letters[i]}: квадрат 4 на 4, разделённый на две части"><rect width="4" height="4" fill="${filled?'#237e79':'#fffefa'}"/>${filled?`<polygon points="${regions[i].map(p=>p.join(',')).join(' ')}" fill="#e9693e"/>`:''}${grid()}<path class="cut" d="${paths[i]}"/><rect class="outline" width="4" height="4"/></svg>`}
const orange=[];const green=[];
for(let y=0;y<4;y++)for(let x=0;x<4;x++)((x===1&&y>=1)||(x===2&&y===3)||(x===3&&y>=1)?orange:green).push([x,y]);
function cells(group,color,prefix){return group.map(([x,y],i)=>`<rect id="${prefix}${i}" class="cell" x="${x}" y="${y}" width="1" height="1" fill="${color}"/><text id="${prefix}n${i}" class="cell-label" x="${x+.5}" y="${y+.5}">${i+1}</text>`).join('')}
function counting(compare){return `<svg viewBox="${compare?'-.5 -.5 10 5':'-1 -.4 6 5'}" role="img" aria-label="Рисунок Д. Оранжевая часть 7 клеток, зелёная часть 9 клеток.">${cells(green,'#237e79','g')}${cells(orange,'#e9693e','o')}${compare?'':`<path class="cut" d="${paths[4]}"/><rect class="outline" width="4" height="4"/>`}<text x="${compare?4.5:2}" y="4.5" style="font-size:.28px;fill:#172e34;text-anchor:middle">${compare?'7 оранжевых + 2 лишние зелёные = 9 зелёных':'3 + 1 + 3 = 7 · 16 − 7 = 9'}</text></svg>`}
function rearrange(){arranged=true;[orange,green].forEach((group,k)=>group.forEach((_,i)=>{const prefix=k?'g':'o',x=i,y=k?2.2:.7;const r=$(prefix+i),n=$(prefix+'n'+i);if(r){r.setAttribute('x',x);r.setAttribute('y',y);n.setAttribute('x',x+.5);n.setAttribute('y',y+.5)}}))}
function schedule(){clearTimeout(timer);if(playing)timer=setTimeout(()=>{if(step<4){step++;render()}else{playing=false;updatePlay()}},7500)}
function updatePlay(){$('play').textContent=playing?'Ⅱ Пауза':'▶ Смотреть';$('play').setAttribute('aria-label',playing?'Приостановить автоматический показ':'Включить автоматический показ');$('play').setAttribute('aria-pressed',String(playing))}
function render(){clearTimeout(moveTimer);arranged=false;$('chapterTag').textContent='МУЛЬТИК · '+steps[step][0].toUpperCase();$('counter').textContent=`0${step+1} / 05`;$('sceneTitle').textContent=steps[step][1];$('sceneText').textContent=steps[step][2];$('chapters').innerHTML=steps.map((s,i)=>`<button data-step="${i}" class="${i===step?'active':''}" ${i===step?'aria-current="step"':''}><span>0${i+1}</span>${s[0]}</button>`).join('');$('feedback').textContent='';
if(step===0){$('stage').innerHTML='<div class="options">'+letters.map((l,i)=>`<button class="option ${selected===i?'selected':''}" data-answer="${i}" aria-label="Выбрать ответ ${l}" aria-pressed="${selected===i}">${square(i)}<strong>${l}</strong></button>`).join('')+'</div>';$('feedback').textContent=selected===null?'Выбери один из пяти рисунков. Потом проверим вместе.':`Твой выбор — ${letters[selected]}. Нажми «Далее», чтобы проверить его по клеткам.`}
if(step===1){$('stage').innerHTML=`<svg viewBox="-1 -.4 6 5" role="img" aria-label="Квадрат 4 на 4, 16 клеток"><rect width="4" height="4" fill="#eaf0e6"/>${Array.from({length:16},(_,i)=>`<text x="${i%4+.5}" y="${Math.floor(i/4)+.58}" style="font-size:.3px;text-anchor:middle;fill:#237e79">${i+1}</text>`).join('')}${grid()}<rect class="outline" width="4" height="4"/></svg>`;$('feedback').textContent='Сравниваем количество клеток, а не длину линии и не внешний вид частей.'}
if(step===2){$('stage').innerHTML=counting(false);$('feedback').textContent='Оранжевая: 3 + 1 + 3 = 7. Зелёная: 16 − 7 = 9. Все клетки целые.'}
if(step===3){$('stage').innerHTML=counting(true);$('feedback').textContent='Перемещение клеток не меняет их площадь. Зелёная часть больше на 2 клетки.';moveTimer=setTimeout(rearrange,playing?120:500)}
if(step===4){$('stage').innerHTML='<div class="options">'+letters.map((l,i)=>`<div class="option ${i===4?'selected':''}">${square(i,true)}<strong>${l}</strong><small>${i===4?'7 и 9':'8 и 8'}</small></div>`).join('')+'</div>';$('feedback').textContent=selected===4?'Верно! Твоя догадка подтвердилась: ответ Д.':selected===null?'Теперь ты знаешь, как доказать ответ: Д.':`Ты выбрал ${letters[selected]}. Проверка клетками показала: правильный ответ — Д. Ошибаться и проверять — часть математики!`}
$('back').disabled=step===0;$('next').disabled=step===4;$('progress').style.width=((step+1)*20)+'%';if(step===4)playing=false;updatePlay();schedule()}
function navigate(n){step=Math.max(0,Math.min(4,n));render()}
$('chapters').addEventListener('click',e=>{const b=e.target.closest('[data-step]');if(b)navigate(Number(b.dataset.step))});$('stage').addEventListener('click',e=>{const b=e.target.closest('[data-answer]');if(b){selected=Number(b.dataset.answer);render()}});$('next').onclick=()=>navigate(step+1);$('back').onclick=()=>navigate(step-1);$('repeat').onclick=()=>{selected=null;playing=false;step=0;render()};$('play').onclick=()=>{playing=!playing;if(playing&&step===4){step=0;render()}else{updatePlay();schedule()}};
document.addEventListener('keydown',e=>{if(/INPUT|TEXTAREA|SELECT/.test(e.target.tagName))return;if(e.key==='ArrowRight'){e.preventDefault();navigate(step+1)}if(e.key==='ArrowLeft'){e.preventDefault();navigate(step-1)}if(e.code==='Space'&&e.target===document.body){e.preventDefault();$('play').click()}});document.addEventListener('visibilitychange',()=>{if(document.hidden){playing=false;clearTimeout(timer);updatePlay()}});render();
